// 兼容unity
static void fgui_size_to_luaval(lua_State* L, const ax::Size& sz)
{
    if (NULL == L)
        return;
    lua_newtable(L);                          /* L: table */
    lua_pushstring(L, "x");               /* L: table key */
    lua_pushnumber(L, (lua_Number)sz.width);  /* L: table key value*/
    lua_rawset(L, -3);                        /* table[key] = value, L: table */
    lua_pushstring(L, "y");              /* L: table key */
    lua_pushnumber(L, (lua_Number)sz.height); /* L: table key value*/
    lua_rawset(L, -3);                        /* table[key] = value, L: table */
}

// 兼容unity
static bool fgui_luaval_to_size(lua_State* L, int lo, ax::Size* outValue, const char* funcName = "")
{
    ax::Vec2 value;
    if (luaval_to_vec2(L, lo, &value, funcName))
    {
        outValue->width = value.x;
        outValue->height = value.y;
        return true;
    }
    return false;
}

static bool luaval_is_rect(lua_State* L, int lo)
{
    if (NULL == L)
        return false;

    bool ok = true;

    tolua_Error tolua_err;
    if (!tolua_istable(L, lo, 0, &tolua_err))
    {
        ok = false;
    }

    if (ok)
    {
        lua_pushstring(L, "width");
        lua_gettable(L, lo);
        ok = !lua_isnil(L, -1);
        lua_pop(L, 1);

        if (!ok)
            return ok;

        lua_pushstring(L, "height");
        lua_gettable(L, lo);
        ok = !lua_isnil(L, -1);
        lua_pop(L, 1);
    }

    return ok;
}


static void margin_to_luaval(lua_State* L, const fairygui::Margin& _margin)
{
    lua_newtable(L);
    lua_pushstring(L, "left");
    lua_pushnumber(L, (lua_Number)_margin.left);
    lua_rawset(L, -3);
    lua_pushstring(L, "top");
    lua_pushnumber(L, (lua_Number)_margin.top);
    lua_rawset(L, -3);
    lua_pushstring(L, "right");
    lua_pushnumber(L, (lua_Number)_margin.right);
    lua_rawset(L, -3);
    lua_pushstring(L, "bottom");
    lua_pushnumber(L, (lua_Number)_margin.bottom);
    lua_rawset(L, -3);
}

static bool luaval_to_margin(lua_State* L, int lo, fairygui::Margin* outValue, const char* funcName)
{
    bool ok = true;

    tolua_Error tolua_err;
    if (!tolua_istable(L, lo, 0, &tolua_err)) {
#if _NULL_PTR_CHECK_ENABLED >=1
        luaval_to_native_err(L, "#ferror:", &tolua_err, funcName);
#endif
        ok = false;
    }

    if (ok) {
        lua_pushstring(L, "left");
        lua_gettable(L, lo);
        outValue->left = lua_isnil(L, -1) ? 0 : lua_tonumber(L, -1);
        lua_pop(L, 1);

        lua_pushstring(L, "top");
        lua_gettable(L, lo);
        outValue->top = lua_isnil(L, -1) ? 0 : lua_tonumber(L, -1);
        lua_pop(L, 1);

        lua_pushstring(L, "right");
        lua_gettable(L, lo);
        outValue->right = lua_isnil(L, -1) ? 0 : lua_tonumber(L, -1);
        lua_pop(L, 1);

        lua_pushstring(L, "bottom");
        lua_gettable(L, lo);
        outValue->bottom = lua_isnil(L, -1) ? 0 : lua_tonumber(L, -1);
        lua_pop(L, 1);
    }

    return ok;
}

static bool luaval_to_array_of_float(lua_State* L, int lo, float **floats, int *count, const char* funcName)
{
    if (NULL == L)
        return false;

    bool ok = true;
    tolua_Error tolua_err;

    if (!tolua_istable(L, lo, 0, &tolua_err)) {
#if _NULL_PTR_CHECK_ENABLED >=1
        luaval_to_native_err(L,"#ferror:", &tolua_err, funcName);
#endif
        ok = false;
    }

    if (ok) {
        size_t len = lua_objlen(L, lo);
        if (len > 0) {
            float* array = (float*) new float[len];
            if (NULL == array)
                return false;
            for (size_t i = 0; i < len; ++i) {
                lua_rawgeti(L, lo, i + 1); // +1
                array[i] = (float)lua_tonumber(L, -1);
                lua_pop(L, 1); // -1
            }
            *count = (int)len;
            *floats = array;
        }
    }
    return ok;
}

